// Prepare data: checks the two sheet reads, picks the latest weekly_snapshots row
// and works out the dates. Never throws: every problem goes into errors[] so the
// workflow sends a short alert to TEST_EMAIL instead of the e-mail to Scott.
const S = $('SETTINGS').first().json;
const TZ = S.TIMEZONE || 'America/Sao_Paulo';
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
const errors = [];

// Same date rules as workflow B: serial number, AAAA-MM-DD or DD/MM/AAAA.
function toDateTime(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return DateTime.fromMillis(Math.round((v - 25569) * 86400000), { zone: 'UTC' }).setZone(TZ, { keepLocalTime: true });
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] }, { zone: TZ });
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return DateTime.fromObject({ year: +m[3], month: +m[2], day: +m[1] }, { zone: TZ });
  if (/^\d+(\.\d+)?$/.test(s)) return toDateTime(Number(s));
  return null;
}
function toISODate(v) { const d = toDateTime(v); return d && d.isValid ? d.toISODate() : ''; }

// Reads the output of a Google Sheets node (Continue on fail + Always output data).
function readSheet(nodeName, label) {
  let items;
  try { items = $(nodeName).all(); } catch (e) { errors.push(label + ': the node did not run (' + e.message + ').'); return null; }
  const failed = items.find(i => i.json && i.json.error);
  if (failed) {
    const e = failed.json.error;
    errors.push(label + ': read failed (' + str(typeof e === 'object' ? (e.message || JSON.stringify(e)) : e).slice(0, 300) + ').');
    return null;
  }
  return items.map(i => i.json).filter(r => r && Object.keys(r).some(k => k !== 'row_number' && str(r[k]) !== ''));
}

// ---------- settings
const MODE = str(S.MODE).toLowerCase();
if (MODE !== 'test' && MODE !== 'prod') errors.push('SETTINGS: MODE must be "test" or "prod" (it is "' + str(S.MODE) + '").');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(str(S.TEST_EMAIL))) errors.push('SETTINGS: TEST_EMAIL is not a valid e-mail address.');
if (MODE === 'prod' && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(str(S.SCOTT_EMAIL))) errors.push('SETTINGS: MODE is "prod" but SCOTT_EMAIL is empty or invalid.');
if (MODE === 'prod' && !/^https:\/\//.test(str(S.SITE_BASE_URL))) errors.push('SETTINGS: MODE is "prod" but SITE_BASE_URL is not set.');

// ---------- tasks
const taskRows = readSheet('Read tasks', 'Sheet "tasks"');
if (taskRows) {
  const withId = taskRows.filter(r => str(r.task_id));
  if (!withId.length) errors.push('Sheet "tasks": no rows with a task_id.');
  else {
    for (const col of ['task_id', 'owners', 'status', 'due_date', 'title_en_CA']) {
      if (!withId.some(r => Object.prototype.hasOwnProperty.call(r, col))) errors.push('Sheet "tasks": column "' + col + '" not found.');
    }
  }
}
const tasks = (taskRows || []).filter(r => str(r.task_id)).map(r => ({
  task_id: str(r.task_id),
  title_en_CA: str(r.title_en_CA),
  title_pt_BR: str(r.title_pt_BR),
  owners: str(r.owners),
  status: str(r.status).toLowerCase(),
  due_raw: str(r.due_date),
  due_date: toISODate(r.due_date),
}));
for (const t of tasks) if (t.due_raw && !t.due_date) errors.push('Sheet "tasks": ' + t.task_id + ' has an unreadable due_date ("' + t.due_raw + '").');

// ---------- latest weekly_snapshots row (most recent snapshot_date; on a tie, the lower row)
const snapRows = readSheet('Read weekly_snapshots', 'Sheet "weekly_snapshots"');
let snapshot = null, kpi = null;
if (snapRows) {
  const valid = snapRows
    .map((r, i) => ({ r, i, sd: toISODate(r.snapshot_date), ws: toISODate(r.week_start) }))
    .filter(x => x.sd && x.ws);
  valid.sort((a, b) => (a.sd === b.sd ? b.i - a.i : (a.sd < b.sd ? 1 : -1)));
  if (!valid.length) errors.push('Sheet "weekly_snapshots": no row with a valid snapshot_date and week_start.');
  else {
    const pick = valid[0];
    snapshot = {
      snapshot_date: pick.sd,
      week_start: pick.ws,
      how_its_going_status: str(pick.r.how_its_going_status),
      executing_text_en_CA: str(pick.r.executing_text_en_CA),
      how_its_going_text_en_CA: str(pick.r.how_its_going_text_en_CA),
      what_to_change_text_en_CA: str(pick.r.what_to_change_text_en_CA),
      executing_text_pt_BR: str(pick.r.executing_text_pt_BR),
      how_its_going_text_pt_BR: str(pick.r.how_its_going_text_pt_BR),
      what_to_change_text_pt_BR: str(pick.r.what_to_change_text_pt_BR),
    };
    try {
      kpi = JSON.parse(str(pick.r.kpi_json) || 'null');
      if (!kpi || typeof kpi !== 'object' || Array.isArray(kpi)) { kpi = null; errors.push('weekly_snapshots (' + pick.ws + '): kpi_json is empty or not an object.'); }
    } catch (e) { errors.push('weekly_snapshots (' + pick.ws + '): kpi_json is not valid JSON.'); }
    if (!['Green', 'Yellow', 'Red', 'Gray'].includes(snapshot.how_its_going_status)) errors.push('weekly_snapshots (' + pick.ws + '): how_its_going_status is "' + snapshot.how_its_going_status + '".');
    if (!snapshot.how_its_going_text_en_CA) errors.push('weekly_snapshots (' + pick.ws + '): how_its_going_text_en_CA is empty.');
    const hasTaskLists = kpi && kpi.tasks && typeof kpi.tasks === 'object';
    if (!hasTaskLists && (!snapshot.executing_text_en_CA || !snapshot.what_to_change_text_en_CA)) errors.push('weekly_snapshots (' + pick.ws + '): no kpi.tasks and the English box texts are empty.');
  }
}

// ---------- dates
const now = DateTime.now().setZone(TZ);
const today = now.toISODate();
const monday = now.startOf('week');            // Luxon weeks start on Monday
const sunday = monday.plus({ days: 6 }).toISODate();
const maxAge = Number(S.MAX_SNAPSHOT_AGE_DAYS) || 8;
if (snapshot) {
  const age = Math.round(now.startOf('day').diff(DateTime.fromISO(snapshot.snapshot_date, { zone: TZ }), 'days').days);
  if (age > maxAge) errors.push('weekly_snapshots: the latest snapshot is from ' + snapshot.snapshot_date + ' (' + age + ' days old, limit ' + maxAge + '). Did workflow B run?');
}
const hoursWeek = snapshot ? DateTime.fromISO(snapshot.week_start, { zone: TZ }).toFormat("kkkk-'W'WW") : '';

return [{ json: {
  ok: errors.length === 0,
  errors,
  mode: MODE,
  today, week_monday: monday.toISODate(), week_sunday: sunday,
  hours_week: hoursWeek,
  snapshot, kpi, tasks,
} }];

// Build email: tasks completed last cycle + Scott's open tasks + the Home boxes + hours of the last cycle.
// The same layout is built twice by build(lang): 'en' (en_CA, for Scott) and 'pt' (pt_BR, copy for MY_EMAIL).
// Output: { ok, errors, mode, en: { to, subject, html, text, raw }, pt: { send, to, subject, html, text, raw } }
// — raw is the MIME message (multipart/alternative: text + HTML) for the Gmail API.
// Uses only data from the sheets (Prepare data) and the timelog webhook (Get hours).
const S = $('SETTINGS').first().json;
const P = $('Prepare data').first().json;
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
const errors = (P.errors || []).slice();
const isNum = (n) => typeof n === 'number' && isFinite(n);
const isEmail = (s) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(str(s));

// ---------- hours (same call as the dashboard: public_totals, week of the snapshot)
let hours = null;
{
  let h = null;
  try { h = $('Get hours').first().json; } catch (e) { h = null; }
  if (!h) errors.push('Hours: the timelog webhook did not answer.');
  else if (h.error) errors.push('Hours: timelog webhook failed (' + str(typeof h.error === 'object' ? (h.error.message || JSON.stringify(h.error)) : h.error).slice(0, 200) + ').');
  else if (h.ok !== true || !isNum(h.total_week_hours)) errors.push('Hours: unexpected answer from the timelog webhook.');
  else if (P.hours_week && h.week && h.week !== P.hours_week) errors.push('Hours: asked for ' + P.hours_week + ' but got ' + h.week + '.');
  else hours = h;
}

// ---------- texts per language (en = Canada-style "Nov 25"; pt = dd/mm)
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const pad2 = (x) => String(x).padStart(2, '0');
const TX = {
  en: {
    htmlLang: 'en',
    short: (iso) => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(str(iso)); return m ? MONTHS[+m[2] - 1] + ' ' + (+m[3]) : ''; },
    num: (n) => (Math.round(n * 10) / 10).toString(),
    status: { backlog: 'Not started', next: 'Up next', doing: 'In progress', blocked: 'Blocked' },
    noDeadline: 'No deadline', overdueBadge: 'OVERDUE', wasDue: (d) => 'was due ' + d, due: (d) => 'Due ' + d,
    counts: (o, s, z) => o + ' overdue · ' + s + ' due this week · ' + z + ' no deadline',
    thisWeek: 'This week: ', nextWeek: 'Next week: ', blocked: 'Blocked', lateSince: (d) => 'Late since ' + d,
    cycle: (x, y, l) => x + ' of ' + y + ' in the cycle · ' + l + ' late',
    reason: 'Reason: ', gtm: (a, b, d) => 'Original GTM plan: ' + a + '% done, ' + b + '% expected by ' + d,
    nothing: 'Nothing to list.',
    statusWord: { Green: 'Green', Yellow: 'Yellow', Red: 'Red', Gray: 'Grey' },
    boxes: ['What we are working on', 'How it is going', 'What needs to change'],
    other: 'Other',
    hoursLabel: (r) => 'Hours last cycle (' + r + '): ', totalWord: ' total',
    hoursNone: (r) => 'Hours last cycle (' + r + '): no hours logged for this cycle.',
    subject: (wk, n) => 'GTM weekly update – week of ' + wk + ' – ' + (n === 0 ? 'no open tasks for you' : n + ' open task' + (n === 1 ? '' : 's') + ' for you'),
    topNote: '',
    hello: 'Hi Scott,',
    intro: 'Here is your weekly GTM update: what was completed last week, your open tasks, then a short summary of the week.',
    doneTitle: 'Completed last week', doneRange: (r) => ' (' + r + ')',
    doneTotal: (n) => n + ' task' + (n === 1 ? '' : 's') + ' completed', doneNone: 'No tasks completed in this cycle.',
    doneCols: ['Task', 'Owner', 'Done'], noOwner: 'No owner', doneMore: (n) => '+' + n + ' more',
    doneMoreLink: 'see them on the dashboard', noDateWarn: null,
    tasksTitle: 'Your open tasks', noTasks: 'You have no open tasks this week.',
    cols: ['Task', 'Deadline', 'Status'],
    summary: 'Summary of the week', more: (n) => '+' + n + ' more on the dashboard',
    button: 'Open the dashboard', noUrl: '[TEST] SITE_BASE_URL is not set, so the dashboard link is missing.', linkNotSet: '(link not set)',
    bye: 'Best,', name: 'Rafael',
  },
  pt: {
    htmlLang: 'pt-BR',
    short: (iso) => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(str(iso)); return m ? m[3] + '/' + m[2] : ''; },
    num: (n) => (Math.round(n * 10) / 10).toString().replace('.', ','),
    status: { backlog: 'Não iniciada', next: 'Próxima', doing: 'Em andamento', blocked: 'Bloqueada' },
    noDeadline: 'Sem prazo', overdueBadge: 'ATRASADA', wasDue: (d) => 'prazo era ' + d, due: (d) => 'Prazo ' + d,
    counts: (o, s, z) => o + (o === 1 ? ' atrasada' : ' atrasadas') + ' · ' + s + ' com prazo esta semana · ' + z + ' sem prazo',
    thisWeek: 'Esta semana: ', nextWeek: 'Próxima semana: ', blocked: 'Bloqueada', lateSince: (d) => 'Atrasada desde ' + d,
    cycle: (x, y, l) => x + ' de ' + y + ' no ciclo · ' + l + (l === 1 ? ' atrasada' : ' atrasadas'),
    reason: 'Motivo: ', gtm: (a, b, d) => 'Plano GTM original: ' + a + '% feito, ' + b + '% previsto até ' + d,
    nothing: 'Nada a listar.',
    statusWord: { Green: 'Verde', Yellow: 'Amarelo', Red: 'Vermelho', Gray: 'Cinza' },
    boxes: ['O que estamos fazendo', 'Como está indo', 'O que precisa mudar'],
    other: 'Outras',
    hoursLabel: (r) => 'Horas do último ciclo (' + r + '): ', totalWord: ' no total',
    hoursNone: (r) => 'Horas do último ciclo (' + r + '): nenhuma hora registrada neste ciclo.',
    subject: (wk, n) => 'GTM – atualização semanal – semana de ' + wk + ' – ' + (n === 0 ? 'nenhuma tarefa aberta do Scott' : n + (n === 1 ? ' tarefa aberta' : ' tarefas abertas') + ' do Scott'),
    topNote: 'Cópia para você. O Scott recebeu a versão em inglês.',
    hello: 'Oi,',
    intro: 'Esta é a atualização semanal de GTM: o que foi concluído na semana passada, as tarefas abertas do Scott e um resumo da semana.',
    doneTitle: 'Concluídas na semana passada', doneRange: (r) => ' (' + r + ')',
    doneTotal: (n) => n + (n === 1 ? ' tarefa concluída' : ' tarefas concluídas'), doneNone: 'Nenhuma tarefa concluída neste ciclo.',
    doneCols: ['Tarefa', 'Responsável', 'Concluída em'], noOwner: 'Sem responsável', doneMore: (n) => '+' + n + ' a mais',
    doneMoreLink: 'veja no painel',
    noDateWarn: (n, ids) => 'Aviso só para você: ' + n + (n === 1 ? ' tarefa Concluída está' : ' tarefas Concluídas estão') + ' sem done_on na planilha e não ' + (n === 1 ? 'aparece' : 'aparecem') + ' nesta lista' + (ids.length ? ' (' + ids.join(', ') + ')' : '') + '.',
    tasksTitle: 'Tarefas abertas do Scott', noTasks: 'O Scott não tem tarefas abertas esta semana.',
    cols: ['Tarefa', 'Prazo', 'Status'],
    summary: 'Resumo da semana', more: (n) => '+' + n + ' no painel',
    button: 'Abrir o painel', noUrl: '[TEST] SITE_BASE_URL não está preenchido, então falta o link do painel.', linkNotSet: '(link não definido)',
    bye: 'Abraço,', name: 'Rafael',
  },
};

// ---------- helpers that do not depend on the language
function esc(s) { return str(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function oneLine(s) { return str(s).replace(/\s+/g, ' ').trim(); }
const splitLines = (s) => str(s).split('\n').map(x => x.trim()).filter(Boolean);
const norm = (s) => str(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const arr = (x) => Array.isArray(x) ? x : [];

// ---------- Scott's open tasks (same list for both languages)
const OWNER = norm(S.SCOTT_NAME || 'Scott');
const CLOSED = str(S.CLOSED_STATUSES || 'done,frozen,dropped').split(',').map(norm).filter(Boolean);
const today = P.today, sunday = P.week_sunday;
const mine = (P.tasks || [])
  .filter(t => t.owners.split(',').map(norm).includes(OWNER))   // exact name per comma-separated part
  .filter(t => !CLOSED.includes(t.status))
  .map(t => {
    const d = t.due_date;
    return Object.assign({}, t, { kind: !d ? 'none' : d < today ? 'overdue' : d <= sunday ? 'soon' : 'later' });
  });
const rank = { overdue: 0, soon: 1, later: 1, none: 2 };
mine.sort((a, b) => rank[a.kind] - rank[b.kind] || (a.due_date < b.due_date ? -1 : a.due_date > b.due_date ? 1 : 0) || a.task_id.localeCompare(b.task_id));
const n = mine.length;
const nOver = mine.filter(t => t.kind === 'overdue').length;
const nSoon = mine.filter(t => t.kind === 'soon').length;
const nNone = mine.filter(t => t.kind === 'none').length;

const snap = P.snapshot || {};
const kpi = P.kpi || {};
const T = kpi.tasks && typeof kpi.tasks === 'object' ? kpi.tasks : null;
const MAX = Number(S.MAX_BULLETS) || 3;
const DOT = { Green: 1, Yellow: 1, Red: 1, Gray: 1 };   // known statuses
const in7 = DateTime.fromISO(today).plus({ days: 7 }).toISODate();   // "due within 7 days" (display only)
// Completed last cycle: kpi.tasks.completed_last_cycle of the same snapshot (the same week as the hours). Older snapshots: no section.
const DONE = T && Array.isArray(T.completed_last_cycle) ? T.completed_last_cycle.filter(x => x && str(x.task_id)) : null;
const MAX_DONE = 15;
const noDate = T && T.done_without_date && isNum(T.done_without_date.count) ? T.done_without_date : { count: 0, task_ids: [] };

// ---------- look: 3 highlight colours only (yellow = critical, red = overdue/blocked/Red, green = Green status)
const C = { text: '#1b2430', muted: '#4a5563', line: '#d6dde6', accent: '#1f5fa8', boxBg: '#e9f1fb', band: '#f3f4f6',
  redText: '#9B1C1C', redBg: '#FDE2E2', yelText: '#3d2e00', yelBg: '#FFF3B0', grnText: '#14532d', grnBg: '#dcf3e4', grayText: '#4a5563', grayBg: '#edf0f3' };
const TONE = { red: [C.redBg, C.redText], yellow: [C.yelBg, C.yelText], green: [C.grnBg, C.grnText], gray: [C.grayBg, C.grayText] };
const STATUS_TONE = { Green: 'green', Yellow: 'yellow', Red: 'red', Gray: 'gray' };
const STATUS_ICON = { Green: '✓', Yellow: '!', Red: '✕', Gray: '–' };
function chip(t, tone) {
  const c = TONE[tone] || TONE.gray;
  return '<span style="display:inline-block;padding:2px 7px;border-radius:4px;background:' + c[0] + ';color:' + c[1] + ';font-size:12px;line-height:1.5;font-weight:700;white-space:nowrap;">' + esc(t) + '</span>';
}
// bold for task IDs, dates (Nov 25 / 25/11), percentages, "30 of 31", hours and "11 late"-type counts
const EMPH = /\b[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)*-\d+\b|\b(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \d{1,2}\b|\b\d{2}\/\d{2}\b|\d+(?:[.,]\d+)?%|\b\d+ (?:of|de) \d+\b|\b\d+(?:[.,]\d+)? h\b|\b\d+ (?:late|blocked|atrasadas?|bloqueadas?)(?![\w\u00C0-\u024F])/g;
const escRaw = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');   // keeps spaces
function emph(s) {
  s = str(s); let out = '', last = 0, m;
  EMPH.lastIndex = 0;
  while ((m = EMPH.exec(s))) { out += escRaw(s.slice(last, m.index)) + '<strong>' + escRaw(m[0]) + '</strong>'; last = m.index + m[0].length; }
  return out + escRaw(s.slice(last));
}
const url = /^https:\/\//.test(str(S.SITE_BASE_URL)) ? str(S.SITE_BASE_URL) : '';
const MODE = P.mode;
const test = MODE !== 'prod';

// ---------- one e-mail in one language: { subject, html, text }
function build(lang) {
  const X = TX[lang];
  const COL = lang === 'pt' ? 'pt_BR' : 'en_CA', ALT = lang === 'pt' ? 'en_CA' : 'pt_BR';
  const short = X.short;
  const fmtH = (h) => X.num(h) + ' h';

  // 1. tasks
  const tasks = mine.map(t => Object.assign({}, t, {
    title: oneLine(t['title_' + COL] || t['title_' + ALT] || t.task_id),
    status_label: X.status[t.status] || (t.status ? t.status.charAt(0).toUpperCase() + t.status.slice(1) : '—'),
    due_label: t.kind === 'none' ? X.noDeadline : t.kind === 'overdue' ? X.overdueBadge + ' · ' + X.wasDue(short(t.due_date)) : X.due(short(t.due_date)),
    within7: !!t.due_date && t.due_date >= today && t.due_date <= in7,   // display only: yellow highlight
  }));
  const countsLine = X.counts(nOver, nSoon, nNone);

  // 2. the Home boxes (same rules as site/index.html). Each line: { text, html, crit }
  const item = (id) => (T && T.items && T.items[id]) || {};
  const titleOf = (id) => oneLine(item(id)['title_' + COL] || item(id)['title_' + ALT] || id);
  function teamNames() { const m = {}; arr(T && T.team_needs).forEach(p => { const k = str(p && p.person).toLowerCase(); if (k) m[k] = true; }); return m; }
  function bareTitle(id) {   // "Scott: ask…" -> "Ask…" when every name before ":" is in team_needs
    const t = titleOf(id), m = t.match(/^([^:]{1,80}):\s+(\S[\s\S]*)$/);
    if (!m) return t;
    const names = teamNames(), parts = m[1].split(/\s*(?:,|&|\be\b|\band\b)\s*/i).filter(Boolean);
    if (!parts.length || !parts.every(p => names[p.trim().toLowerCase()])) return t;
    return m[2].charAt(0).toLocaleUpperCase() + m[2].slice(1);
  }
  const plainLine = (s) => ({ text: s, html: emph(s), crit: false });
  const snapText = (base) => str(snap[base + '_' + COL]) || str(snap[base + '_' + ALT]);
  let execLines, howLines, changeLines;
  if (T) {
    const ex = T.executing || {}, ws = str(kpi.week_start), we = str(kpi.week_end);
    execLines = arr(ex.this_week).map(id => { const d = str(item(id).due_date); return (d && ws && we && d >= ws && d <= we ? X.thisWeek : '') + bareTitle(id); })
      .concat(arr(ex.next_week).map(id => X.nextWeek + bareTitle(id))).map(plainLine);
    changeLines = arr(T.to_change).map(id => {
      const it = item(id), why = [];   // why: { t, red }
      if (it.status === 'blocked') why.push({ t: X.blocked, red: true });
      if (it.due_date && it.due_date < str(T.base_date) && it.status !== 'done') why.push({ t: X.lateSince(short(it.due_date)), red: true });
      if (it.change_note) why.push({ t: oneLine(it.change_note), red: false });
      const title = titleOf(id);
      return {
        text: title + (why.length ? ' (' + why.map(w => w.t).join(' · ') + ')' : ''),
        html: emph(title) + why.map(w => ' ' + (w.red ? chip(w.t, 'red') : '<span style="color:' + C.muted + ';">(' + emph(w.t) + ')</span>')).join(''),
        crit: why.some(w => w.red),
      };
    });
    const c = T.cycle || {}, g = T.gtm_original || {}, late = isNum(T.late_count) ? T.late_count : 0;
    howLines = [splitLines(snapText('how_its_going_text'))[0] || ''].filter(Boolean);
    if (isNum(c.done) && isNum(c.total)) howLines.push(X.cycle(c.done, c.total, late));
    if (T.forced_color && str(T.forced_reason)) howLines.push(X.reason + oneLine(T.forced_reason));
