// ---------- MIME (multipart/alternative) for the Gmail API
function b64(s) {   // UTF-8 -> base64, no Buffer needed
  const bytes = unescape(encodeURIComponent(s)), A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes.charCodeAt(i), b = bytes.charCodeAt(i + 1), c = bytes.charCodeAt(i + 2);
    const t = (a << 16) | ((b || 0) << 8) | (c || 0);
    out += A[(t >> 18) & 63] + A[(t >> 12) & 63] + (i + 1 < bytes.length ? A[(t >> 6) & 63] : '=') + (i + 2 < bytes.length ? A[t & 63] : '=');
  }
  return out;
}
const wrap76 = (s) => s.replace(/.{1,76}/g, '$&\r\n');
function mimeRaw(to, mail, tag) {
  const boundary = 'dcti-' + tag + '-' + Date.now().toString(36);
  const mime = [
    'To: ' + to,
    'Subject: =?UTF-8?B?' + b64(mail.subject) + '?=',
    'MIME-Version: 1.0',
    'Content-Type: multipart/alternative; boundary="' + boundary + '"', '',
    '--' + boundary, 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', wrap76(b64(mail.text)),
    '--' + boundary, 'Content-Type: text/html; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', wrap76(b64(mail.html)),
    '--' + boundary + '--', '',
  ].join('\r\n');
  return b64(mime).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

